SET LOCAL search_path = pilot_r1, public, pg_catalog;

-- Ежедневники РФ, РОП и РОО: перенос 28 жёстких задач старого портала.
--
-- Что было. Миграция 015 завела ежедневник-заглушку: три свободных поля,
-- одинаковые для всех трёх ролей. Ни одной жёсткой задачи в портале не было.
--
-- Что становится. Структура перенесена из рабочего ежедневника старого портала
-- (/opt/fresh-dashboard-src/ежедневные-отчёты/public/index.html): 28 задач с
-- распределением по ролям manager → РФ, rop → РОП, roo → РОО, с теми же
-- полями, единицами измерения, списками значений и повторяемыми блоками ТС,
-- звонков, клиентов и встреч. Поля не придуманы: они извлечены из формы
-- автоматически, разбор сохранён в репозитории (server/scripts/dailySchema.json).
--
-- Распределение: РФ — задачи 1, 4–9, 14, 27, 28; РОП — 1, 2, 10–12, 15–18, 26,
-- 28; РОО — 1, 3, 13, 19–25, 28. Задачи 5–8 (анализ доли 45+, трафика, склада,
-- КСО) помечены необязательными, как в старом портале.
--
-- Отметка выполнения каждой задачи — поле t<N>_done со значениями
-- «Выполнено» / «Не выполнено», аналог галочки старой формы. Обязательным
-- остаётся только итог дня: движок требует completion_summary при сдаче.
-- Остальные поля необязательные — иначе ежедневник нельзя будет сдать в день,
-- когда часть задач не применима.
--
-- Общий блок задачи 1 «План на день» (продажи, поставки, КМ) закреплён за РФ:
-- в старом портале его заполнял руководитель филиала, а РОП и РОО видели.
-- Сквозная видимость между ежедневниками разных ролей — отдельный шаг.
--
-- Новые шаблоны заведены как отдельный код _v2. Записи ежедневников, созданные
-- по _v1, остаются привязанными к своей версии шаблона, поэтому история
-- заполнения не переписывается.
--
-- Аддитивная. Повторный прогон безопасен.
-- Неразрушающий откат: вернуть код шаблона _v1 в server/src/domain/dailyLogs.ts.
--   Строки не удаляются.


